    "correctIndex": 0,
    "hintEn": "Set $y_1 = y_2 \\implies ${mSq} - x^2 = x^2 - ${mSq} \\implies x = \\pm ${m}$. Area $= 2 \\int_0^{${m}} 2(${mSq} - x^2) dx = \\frac{8}{3}(${m})^3$.",
    "hintAr": "بمساواة المنحنيين نجد نقاط التقاطع $x = \\pm ${m}$. المساحة $= \\frac{8}{3}(${m})^3$.",
